"""Portable, immutable training recipes generated by the control panel."""
import copy
import hashlib
import json
import math
import re
import uuid
from pathlib import Path
from robocub.user_cli.policy_library import inside, read


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def build_recipe(root, entry, row, values, source, mode, base_config=None):
    original = read(inside(root, entry['configuration']))
    config = copy.deepcopy(base_config if base_config is not None else original)
    if config.get('robot',{}).get('name') != 'unitree_g1' or config.get('env',{}).get('name') != 'unitree_g1_playground':
        raise ValueError('This launcher supports the registered G1 Playground task')
    if mode == 'Continue weights':
        for key in ('policy_hidden_layer_sizes','value_hidden_layer_sizes','normalize_observations'):
            if config['agent'].get(key) != original['agent'].get(key):
                raise ValueError('Checkpoint network architecture/normalization must match; use New training for architecture changes')
    if not config or source not in ('local', 'atlantis') or mode not in ('New training', 'Continue weights'):
        raise ValueError('Choose a valid configuration, compute source and training mode')
    agent = config['agent']
    for key in ('num_envs','seed','num_timesteps','batch_size','unroll_length','num_minibatches','num_evals'):
        value = int(values[key])
        if value < (0 if key == 'seed' else 1): raise ValueError(f'{key} is out of range')
        agent[key] = value
    for key in ('learning_rate','discounting','entropy_cost'):
        value = float(values[key])
        if not math.isfinite(value) or value < 0: raise ValueError(f'{key} must be finite and nonnegative')
        agent[key] = value
    if not 0 < agent['learning_rate'] <= 1 or not 0 < agent['discounting'] <= 1:
        raise ValueError('Learning rate and discount must be in (0, 1]')
    if agent['batch_size'] * agent['num_minibatches'] % agent['num_envs']:
        raise ValueError('Batch size × minibatches must be divisible by environment count')
    hours = int(values['hours'])
    cpus, memory = int(values['cpus']), int(values['memory_gb'])
    if not 1 <= hours <= 24 or not 1 <= cpus <= 8 or not 8 <= memory <= 32:
        raise ValueError('Use 1–24 hours, 1–8 CPUs and 8–32 GiB RAM')
    assets = []
    checkpoint = None
    if mode == 'Continue weights':
        if not row or not row['ready']: raise ValueError('Select an available checkpoint')
        checkpoint = row['weights'].parent.relative_to(root).as_posix()
        for file in row['weights'].parent.rglob('*'):
            if file.is_file():
                safe = inside(root, str(file))
                assets.append({'path': safe.relative_to(root).as_posix(), 'sha256': digest(safe)})
        if not assets: raise ValueError('Checkpoint has no files')
    return dict(version=1, source=source, mode=mode, policy=entry['name'],
                config=config, checkpoint=checkpoint, input_assets=assets,
                exact_resume=False, hours=hours, resources=dict(cpus=cpus,memory_gb=memory,hours=hours,gpu_type='rtx2080ti'))


def training_argv(recipe, output):
    cfg = recipe['config']
    # Groups establish schemas; explicit saved settings then override every leaf.
    args = ['robocub/scripts/train.py','--logger','local','--video' if recipe.get('record_video',False) else '--no-video','--seed',str(cfg['agent']['seed'])]
    if recipe['checkpoint']: args += ['--resume','--checkpoint','{root}/'+recipe['checkpoint']]
    for group in ('env','robot','sim','agent'):
        name = cfg[group]['name'] if group != 'sim' else 'unitree_g1_playground'
        args.append(f'{group}={name}')
    def leaves(value, prefix=''):
        for key, item in value.items():
            path = f'{prefix}.{key}' if prefix else key
            if isinstance(item,dict): yield from leaves(item,path)
            else: yield path,item
    for key,value in leaves(cfg):
        if key.endswith(('.source_root','.cache_root')): value = None
        args.append('++'+key+'='+json.dumps(value,separators=(',',':')))
    args += ['robot.fetch_model=false','sim.playground.fetch_source=true',
             'hydra.run.dir={root}/'+output,'hydra.job.chdir=true']
    return args


def save_recipe(root, recipe):
    identifier = 'ui_' + uuid.uuid4().hex[:12]
    base = 'Configs/training_recipes/' + identifier
    folder = root/base
    folder.mkdir(parents=True,exist_ok=False)
    output = 'Artifacts/Results/'+identifier+'/train'
    plan = dict(version=1,output_dir='Artifacts/Results/'+identifier+'/queue',
                max_wall_seconds=recipe['hours']*3600, input_assets=recipe['input_assets'],
                jobs=[dict(id='train',hypothesis='User-configured walking training recipe',
                    evidence='Explicit panel recipe; development only, no validation claim',
                    review_artifact=output+'/run_manifest.json',stages=[dict(id='train',
                        argv=training_argv(recipe,output),fresh_paths=[output],
                        required_paths=[output+'/run_manifest.json'],timeout_seconds=recipe['hours']*3600-60)])])
    for name,data in [('recipe.json',recipe),('plan.json',plan)]:
        (folder/name).write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
    entry = dict(id=identifier,enabled=False,source=recipe['source'],plan=base+'/plan.json',
                 sha256=digest(folder/'plan.json'),resources=recipe['resources'])
    (folder/'registration.json').write_text(json.dumps(entry,indent=2)+'\n',encoding='utf-8')
    return entry
